class Solution {
    public TreeNode deleteBST(TreeNode root, int key) {
        if (root == null) {
            return null;
        }
        if (key < root.val) {
            root.left = deleteBST(root.left, key);
        } else if (key > root.val) {
            root.right = deleteBST(root.right, key);
        } else {
            return root.left;
        }
        return root;
    }
}
